function exportDialog(){stop();modal(`<h2>Let your story out.</h2><p>${esc(project.name)} · ${duration().toFixed(2)} seconds · ${project.fps} fps</p><div class="exportchoice"><strong>MP4 video</strong><p>A real H.264 video, rendered frame by frame. No watermarks. Includes frame sound effects. Browser H.264 / AAC encoder support required.</p><label class="field">Resolution<select id="exportRes"><option value="1280">${project.format==='9:16'?'HD · 720 × 1280':'HD · 1280 × 720'}</option><option value="1920">${project.format==='9:16'?'Full HD · 1080 × 1920':'Full HD · 1920 × 1080'}</option></select></label><button class="primary wide" id="renderMP4">Export MP4 ↗</button><button id="recordMP4" class="wide" style="margin-top:7px">Real-time recording (fallback)</button><p id="exportStatus" role="status"></p><progress id="exportProgress" max="1" value="0" hidden></progress><button id="cancelExport" class="wide" hidden>Cancel export</button></div><div class="exportchoice"><strong>Animated HTML</strong><p>One portable file with your artwork, animation, playback controls and fullscreen. Works offline in a browser.</p><button id="htmlExport" class="wide">Export HTML ↗</button></div><p>Keep this tab open during export. Save project keeps the editable version.</p>`);$('#htmlExport').onclick=exportHTML;$('#renderMP4').onclick=()=>exportVideo(false);$('#recordMP4').onclick=()=>exportVideo(true);$('#cancelExport').onclick=()=>abortExport?.abort()}
async function realtimeVideo(p,width,height,signal,onProgress){if(!window.MediaRecorder)throw Error('This browser does not support video recording.');const mp4Types=['video/mp4;codecs=avc1.42E01E','video/mp4;codecs=avc1','video/mp4'];const type=mp4Types.find(t=>MediaRecorder.isTypeSupported(t))||['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!type)throw Error('No supported video recorder found.');if(!type.startsWith('video/mp4'))$('#exportStatus').textContent='MP4 recording unavailable here. Recording a correctly labeled WebM video instead.';let c=document.createElement('canvas');c.width=width;c.height=height;let cx=c.getContext('2d',{alpha:false});await M.ready(p);M.render(cx,M.sample(p,0),0,width,height);const stream=c.captureStream(p.fps),recorder=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:8e6}),chunks=[],total=p.frames.reduce((a,f)=>a+f.duration,0);return await new Promise((resolve,reject)=>{let timer,start=0,err=null;const cleanup=()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());signal.removeEventListener('abort',cancel)};const cancel=()=>{err=Error('Export cancelled.');if(recorder.state!=='inactive')recorder.stop();else{cleanup();reject(err)}};signal.addEventListener('abort',cancel);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=e=>{err=e.error||Error('Recording failed.');cleanup();reject(err)};recorder.onstop=()=>{cleanup();if(err)return reject(err);resolve(new Blob(chunks,{type:recorder.mimeType||type}))};recorder.start(1000);start=performance.now();function step(){if(signal.aborted)return;let t=(performance.now()-start)/1000;M.render(cx,M.sample(p,Math.min(t,total-.00001)),Math.min(t,total),width,height);onProgress(Math.min(1,t/total));if(t>=total){recorder.stop();return}timer=setTimeout(step,1000/p.fps)}step()})}
async function exportVideo(realtime){exporting=true;abortExport=new AbortController;$('#exportProgress').hidden=false;$('#cancelExport').hidden=false;$$('#modal button:not(#cancelExport)').forEach(b=>b.disabled=true);$('#exportStatus').textContent=realtime?'Recording in real time. Keep this tab visible…':'Preparing the H.264 encoder…';let long=Number($('#exportRes').value),width=project.format==='9:16'?long*9/16:long,height=project.format==='9:16'?long:long*9/16;try{const p=clone(project),onProgress=v=>{$('#exportProgress').value=v;if(!realtime)$('#exportStatus').textContent=`Rendering ${Math.round(v*100)}% · ${Math.ceil(v*duration()*project.fps)} frames`};const blob=realtime?await realtimeVideo(p,width,height,abortExport.signal,onProgress):await MotionMP4.encode({project:p,width,height,signal:abortExport.signal,onProgress});if(blob.size<100)throw Error('The recorder produced an empty file.');const ext=blob.type.startsWith('video/mp4')?'mp4':'webm';download(blob,safeName()+'.'+ext);$('#exportStatus').textContent=`Export complete · ${(blob.size/1048576).toFixed(1)} MB · ${ext.toUpperCase()}`;toast('Your animation is ready.')}catch(e){$('#exportStatus').textContent=e.message;toast(e.message)}finally{exporting=false;$('#cancelExport').hidden=true;$$('#modal button').forEach(b=>b.disabled=false)}}
