function zoomViewport(v){viewZoom=Math.max(.3,Math.min(2,v));stage.style.transform=`scale(${viewZoom})`;$('#zoomLabel').textContent=Math.round(viewZoom*100)+'%'}$('#zoomIn').onclick=()=>zoomViewport(viewZoom+.1);$('#zoomOut').onclick=()=>zoomViewport(viewZoom-.1);$('#fitBtn').onclick=()=>zoomViewport(1);
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('#modal').open)return;const mod=e.ctrlKey||e.metaKey;if(mod&&['z','Z','y'].includes(e.key)){e.preventDefault();e.shiftKey||e.key==='y'?redo():undo();return}if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return}if(mod&&e.key==='d'){e.preventDefault();duplicateObjects();return}if(mod&&e.key==='g'){e.preventDefault();groupSelection();return}if(mod&&e.key==='a'){e.preventDefault();selected=frame().objects.filter(o=>!o.locked&&o.visible).map(o=>o.id);refreshUI();return}if(e.code==='Space'){e.preventDefault();play();return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteObjects();return}if(e.key==='Escape'){selected=[];setTool('select');refreshUI();return}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selected.length){e.preventDefault();remember();let dx=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0,dy=e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0;dx*=e.shiftKey?10:1;dy*=e.shiftKey?10:1;selectedObjects().forEach(o=>{o.x+=dx;o.y+=dy;o.path?.forEach(p=>{p.x+=dx;p.y+=dy})});changed();return}const keys={v:'select',r:'rect',o:'circle',t:'text',p:'path'};if(keys[e.key])setTool(keys[e.key])});
